@layer components {
  :where([data-control-family="tabs"][data-slot="root"]) {
    position: relative;
    display: flex;
    flex-direction: column;
    --cui-tabs-trigger-radius: var(--radius-control);
    --cui-tabs-trigger-padding-inline: calc(var(--spacing) * 3.5);
    --cui-tabs-list-padding: calc(var(--spacing) * 1);
    --cui-tabs-list-radius: var(
      --nest-radius,
      calc(var(--cui-tabs-trigger-radius) + clamp(0px, calc(var(--cui-tabs-trigger-radius) * 1000), var(--cui-tabs-list-padding)))
    );
    --cui-tabs-list-background: var(--hover-fill);
    --cui-tabs-list-shadow: inset 0 0 0 var(--control-rim-width) var(--control-rim), var(--shadow-inset);
    --cui-tabs-list-backdrop-filter: none;
    --cui-tabs-indicator-background: var(--background);
    --cui-tabs-indicator-background-image: none;
    --cui-tabs-surface-background: var(--background);
    --cui-tabs-surface-radius: var(--radius-panel);
    --cui-tabs-foreground: var(--muted-foreground);
    --cui-tabs-active-foreground: var(--foreground);
    --cui-tabs-hover-foreground: var(--foreground);
    --cui-tabs-indicator-shadow: var(--shadow-sm);
    --cui-tabs-border-color: var(--border);
    --cui-tabs-border-width: var(--control-rim-width);
    --cui-tabs-font-size: var(--text-label);
    --cui-tabs-font-weight: var(--font-weight-medium);
    --cui-tabs-scroll-fade-size: calc(var(--spacing) * 6);
  }

  :where([data-control-family="tabs"][data-slot="root"][data-orientation="vertical"]) {
    flex-direction: row;
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="tabs"][data-slot="list"]) {
    --cui-tabs-trigger-height: var(--control-h-sm);
    --cui-tabs-trigger-padding-inline-start: var(--cui-tabs-trigger-padding-inline);
    --cui-tabs-trigger-padding-inline-end: var(--cui-tabs-trigger-padding-inline);
    --_tabs-trigger-radius-fit: min(
      max(
        0px,
        calc(var(--nest-radius, calc(var(--cui-tabs-trigger-radius) + var(--cui-tabs-list-padding))) - var(--cui-tabs-list-padding))
      ),
      calc(var(--cui-tabs-trigger-height) / 2)
    );
    position: relative;
    display: flex;
    min-block-size: calc(var(--cui-tabs-trigger-height) + var(--cui-tabs-list-padding) + var(--cui-tabs-list-padding));
    inline-size: fit-content;
    align-items: center;
    gap: calc(var(--spacing) * 1);
    border-radius: min(var(--cui-tabs-list-radius), calc(var(--cui-tabs-trigger-height) / 2 + var(--cui-tabs-list-padding)));
    background: var(--cui-tabs-list-background);
    box-shadow: var(--cui-tabs-list-shadow);
    padding: var(--cui-tabs-list-padding);
    -webkit-backdrop-filter: var(--cui-tabs-list-backdrop-filter);
    backdrop-filter: var(--cui-tabs-list-backdrop-filter);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-size="xs"]) {
    --cui-tabs-trigger-height: var(--control-h-xs);
    --cui-tabs-font-size: var(--text-caption);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-size="md"]) {
    --cui-tabs-trigger-height: var(--control-h-md);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-size="lg"]) {
    --cui-tabs-trigger-height: var(--control-h-lg);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-scrollable="true"]) {
    --focus-ring-offset: calc(var(--focus-ring-width) * -1);
    max-inline-size: 100%;
    overflow: auto hidden;
    overscroll-behavior-x: contain;
    scroll-padding: var(--cui-tabs-list-padding);
    scrollbar-width: none;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-scrollable="true"][data-orientation="vertical"]) {
    max-block-size: 100%;
    overflow: hidden auto;
  }

  /* Scrollable lists fade the edge that still hides tabs. A scroll timeline drives the fade sizes, so a list that
     fits has an inactive timeline and no fade; browsers without scroll timelines keep the hard edge. */
  @supports (animation-timeline: scroll()) {
    :where([data-control-family="tabs"][data-slot="list"][data-scrollable="true"]) {
      --_tabs-scroll-fade-direction: to right;
      /* Keyboard focus scrolls a tab clear of the fade, so its focus ring stays unmasked. */
      scroll-padding-inline: calc(var(--cui-tabs-list-padding) + var(--cui-tabs-scroll-fade-size));
      mask-image: linear-gradient(
        var(--_tabs-scroll-fade-direction),
        oklch(0 0 0 / 0),
        oklch(0 0 0) var(--_tabs-scroll-fade-start),
        oklch(0 0 0) calc(100% - var(--_tabs-scroll-fade-end)),
        oklch(0 0 0 / 0)
      );
      animation:
        cui-tabs-scroll-fade-start linear both,
        cui-tabs-scroll-fade-end linear both;
      animation-timeline: scroll(self inline), scroll(self inline);
      animation-range:
        0 var(--cui-tabs-scroll-fade-size),
        calc(100% - var(--cui-tabs-scroll-fade-size)) 100%;
    }

    :where([data-control-family="tabs"][data-slot="list"][data-scrollable="true"]:not([data-orientation="vertical"]):dir(rtl)) {
      --_tabs-scroll-fade-direction: to left;
    }

    :where([data-control-family="tabs"][data-slot="list"][data-scrollable="true"][data-orientation="vertical"]) {
      --_tabs-scroll-fade-direction: to bottom;
      scroll-padding-inline: var(--cui-tabs-list-padding);
      scroll-padding-block: calc(var(--cui-tabs-list-padding) + var(--cui-tabs-scroll-fade-size));
      animation-timeline: scroll(self block), scroll(self block);
    }
  }

  @keyframes cui-tabs-scroll-fade-start {
    from {
      --_tabs-scroll-fade-start: 0px;
    }
    to {
      --_tabs-scroll-fade-start: var(--cui-tabs-scroll-fade-size);
    }
  }

  @keyframes cui-tabs-scroll-fade-end {
    from {
      --_tabs-scroll-fade-end: var(--cui-tabs-scroll-fade-size);
    }
    to {
      --_tabs-scroll-fade-end: 0px;
    }
  }

  :where([data-control-family="tabs"][data-slot="indicator"]) {
    position: absolute;
    top: 50%;
    left: 0;
    z-index: 0;
    block-size: var(--cui-tabs-trigger-height);
    inline-size: var(--active-tab-width);
    transform: translateX(var(--active-tab-left)) translateY(-50%);
    border-radius: var(--_tabs-trigger-radius-fit);
    background-color: var(--cui-tabs-indicator-background);
    background-image: var(--cui-tabs-indicator-background-image);
    box-shadow: var(--cui-tabs-indicator-shadow);
    /* Compositor transforms tear the strip while its width resizes. */
    transition:
      width var(--duration-base) var(--ease-standard),
      left var(--duration-base) var(--ease-standard),
      transform var(--duration-base) var(--ease-standard),
      background-color var(--duration-fast) var(--ease-standard),
      box-shadow var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="tabs"][data-slot="list"][data-orientation="vertical"]) {
    flex-direction: column;
    align-items: stretch;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-orientation="vertical"] [data-slot="indicator"]) {
    top: 0;
    block-size: var(--active-tab-height);
    transform: translate(var(--active-tab-left), var(--active-tab-top));
  }

  :where([data-control-family="tabs"][data-slot="tab"]) {
    position: relative;
    z-index: 1;
    display: inline-flex;
    block-size: var(--cui-tabs-trigger-height);
    flex-shrink: 0;
    cursor: pointer;
    align-items: center;
    justify-content: center;
    gap: calc(var(--spacing) * 1.5);
    white-space: nowrap;
    border-radius: var(--_tabs-trigger-radius-fit);
    padding-inline: var(--cui-tabs-trigger-padding-inline-start) var(--cui-tabs-trigger-padding-inline-end);
    color: var(--cui-tabs-foreground);
    font-size: var(--cui-tabs-font-size);
    font-weight: var(--cui-tabs-font-weight);
  }

  :where([data-control-family="tabs"][data-slot="tab"] > svg) {
    inline-size: calc(var(--spacing) * 4);
    block-size: calc(var(--spacing) * 4);
    flex-shrink: 0;
  }

  :where([data-control-family="tabs"][data-slot="list"]:not([data-orientation="vertical"], [data-variant="browser"]) [data-slot="tab"]) {
    flex-grow: 1;
  }

  @media (hover: hover) {
    :where([data-control-family="tabs"][data-slot="tab"]:hover:not([data-disabled])) {
      color: var(--cui-tabs-hover-foreground);
    }
  }

  :where([data-control-family="tabs"][data-slot="tab"]:is([aria-selected="true"], [data-active])) {
    color: var(--cui-tabs-active-foreground);
  }

  :where([data-control-family="tabs"][data-slot="tab"][data-disabled]) {
    cursor: not-allowed;
    opacity: var(--disabled-opacity);
  }

  @media (forced-colors: active) {
    :where([data-control-family="tabs"][data-slot="list"]:not([data-variant="browser"], [data-single="true"])) {
      outline: 1px solid CanvasText;
      outline-offset: -1px;
    }

    :where([data-control-family="tabs"][data-slot="list"]:not([data-variant="browser"]) [data-slot="indicator"]) {
      outline: var(--focus-ring-width) solid Highlight;
      outline-offset: calc(var(--focus-ring-width) * -1);
    }
  }

  :where([data-control-family="tabs"][data-slot="list"][data-single="true"]) {
    min-block-size: auto;
    gap: 0;
    border-radius: 0;
    background: transparent;
    padding: 0;
  }

  :where([data-control-family="tabs"][data-slot="list"][data-single="true"] [data-slot="tab"]) {
    block-size: auto;
    cursor: default;
    border-radius: 0;
    padding-inline: 0;
    color: var(--muted-foreground);
  }

  :where([data-control-family="tabs"][data-slot="panel"]) {
    min-block-size: 0;
    outline-style: none;
  }

  :where([data-control-family="tabs"][data-slot="root"][data-orientation="vertical"] > [data-slot="panel"]) {
    min-inline-size: 0;
    flex: 1;
  }

  :where(
    [data-control-family="tabs"][data-slot="list"][data-orientation="horizontal"]:not([data-variant="browser"]) ~ [data-slot="panel"]
  ) {
    margin-block-start: calc(var(--spacing) * 3);
  }

  :where([data-control-family="tabs"][data-slot="surface"]) {
    min-inline-size: 0;
    border: var(--cui-tabs-border-width) solid var(--cui-tabs-border-color);
    border-radius: var(--cui-tabs-surface-radius);
    background: var(--cui-tabs-surface-background);
  }

  :where([data-control-family="tabs"][data-slot="tab"][data-closable="true"]) {
    padding-inline-end: calc(var(--cui-tabs-trigger-padding-inline-end) + var(--control-h-xs));
  }

  :where([data-control-family="tabs"][data-slot="tab-frame"] > [data-tabs-close="true"]) {
    inset-inline-end: var(--spacing);
  }

  :where(
    [data-control-family="tabs"][data-slot="list"]:not([data-orientation="vertical"], [data-variant="browser"]) [data-slot="tab-frame"]
  ) {
    flex-grow: 1;
  }

  @media (pointer: coarse) {
    :where([data-control-family="tabs"][data-slot="list"]:not([data-single="true"]) [data-slot="tab"])::after {
      content: "";
      position: absolute;
      inset-inline: 0;
      inset-block-start: 50%;
      translate: 0 -50%;
      block-size: max(100%, var(--touch-target));
    }

    :where([data-control-family="tabs"][data-slot="list"][data-orientation="vertical"]:not([data-single="true"]) [data-slot="tab"])::after {
      inset-block: 0;
      inset-inline: min(0px, calc((100% - var(--touch-target)) / 2));
      translate: none;
      block-size: auto;
    }
  }
}

